CREATE TABLE IF NOT EXISTS credentials(user_id TEXT PRIMARY KEY REFERENCES users(id), username TEXT NOT NULL UNIQUE, salt TEXT NOT NULL, verifier TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_limits(key TEXT PRIMARY KEY, window INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS team_members(team_id TEXT NOT NULL REFERENCES teams(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','member')), PRIMARY KEY(team_id,user_id));
CREATE TRIGGER IF NOT EXISTS team_capacity BEFORE INSERT ON team_members WHEN (SELECT COUNT(*) FROM team_members WHERE team_id=NEW.team_id)>=10 AND NOT EXISTS(SELECT 1 FROM team_members WHERE team_id=NEW.team_id AND user_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'Team is full (10 members)'); END;
CREATE TABLE IF NOT EXISTS invitations(id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, team_id TEXT NOT NULL REFERENCES teams(id), project_id TEXT REFERENCES projects(id), role TEXT NOT NULL CHECK(role IN ('editor','viewer')), created_by TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL, claimed_by TEXT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, description TEXT NOT NULL, assignee TEXT REFERENCES users(id), status TEXT NOT NULL DEFAULT 'todo', version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS comments(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), task_id TEXT REFERENCES tasks(id), user_id TEXT NOT NULL REFERENCES users(id), text TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS handoffs(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), from_user TEXT NOT NULL REFERENCES users(id), to_user TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, context TEXT NOT NULL, next_steps TEXT NOT NULL, event_id TEXT, task_id TEXT REFERENCES tasks(id), status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS tasks_project ON tasks(project_id,updated_at);
CREATE INDEX IF NOT EXISTS comments_project ON comments(project_id,created_at);
CREATE INDEX IF NOT EXISTS handoffs_project ON handoffs(project_id,created_at);
CREATE TABLE IF NOT EXISTS backup_objects(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), user_id TEXT NOT NULL REFERENCES users(id), checkpoint_id TEXT NOT NULL, size INTEGER NOT NULL, digest TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS backups_owner ON backup_objects(project_id,user_id);
CREATE TRIGGER IF NOT EXISTS backup_quota BEFORE INSERT ON backup_objects WHEN (SELECT COALESCE(SUM(size),0) FROM backup_objects WHERE project_id=NEW.project_id AND user_id=NEW.user_id)+NEW.size>536870912 BEGIN SELECT RAISE(ABORT,'Backup quota exceeded (512 MiB per member per project)'); END;
